python3 -c "
import json
with open('/app/resources/treasury_bulletin_2000_09.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def find_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(f'{path}{k}')
            if isinstance(v, (dict, list)):
                find_keys(v, path + '  ')
    elif isinstance(obj, list) and len(obj) > 0:
        find_keys(obj[0], path + '[0] ')

find_keys(data)
